/**
 * @description Bodies longer than a transaction field (131,072 characters): the field keeps the first part and the full
 * body is saved as a File on the transaction, titled "Response body <transaction>" or "Callback body <transaction>".
 * @group Integration Hub
 */
public with sharing class IntegrationHubBodyFiles {

    /** @description Length of the body fields on the transaction and the attempt. */
    public static final Integer FIELD_MAX = 131072;
    /** @description Title start of the File with the full answer of a send. */
    public static final String RESPONSE_PREFIX = 'Response body ';
    /** @description Title start of the File with the full callback body. */
    public static final String CALLBACK_PREFIX = 'Callback body ';
    /** @description Title start of a File with the full request body. */
    public static final String REQUEST_PREFIX = 'Request body ';

    /**
     * @description The File for a body that does not fit the field, not inserted.
     * @param transactionId the transaction the File belongs to
     * @param title the File title, e.g. RESPONSE_PREFIX + the transaction Name
     * @param body the full body
     * @return the File version, or null when the body fits the field
     */
    public static ContentVersion fileFor(Id transactionId, String title, String body) {
        if (transactionId == null || body == null || body.length() <= FIELD_MAX) {
            return null;
        }
        return new ContentVersion(Title = title, PathOnClient = title + '.json', VersionData = Blob.valueOf(body),
            FirstPublishLocationId = transactionId);
    }

    /**
     * @description Files for answers of sends longer than the Response Body field, not inserted.
     * @param deliveries the deliveries of a send job
     * @return the Files (null for answers that fit)
     */
    public static List<ContentVersion> responseFiles(List<IntegrationHubCallout.Delivery> deliveries) {
        List<ContentVersion> files = new List<ContentVersion>();
        for (IntegrationHubCallout.Delivery d : deliveries) {
            if (d.res != null) {
                files.add(fileFor(d.txn.Id, RESPONSE_PREFIX + d.txn.Name, d.res.getBody()));
            }
        }
        return files;
    }

    /**
     * @description Inserts the Files; null entries are skipped. A File that cannot be saved does not stop the caller.
     * @param files the File versions (may hold nulls)
     */
    public static void save(List<ContentVersion> files) {
        List<ContentVersion> rows = new List<ContentVersion>();
        for (ContentVersion cv : files == null ? new List<ContentVersion>() : files) {
            if (cv != null) {
                rows.add(cv);
            }
        }
        IntegrationHubData.insertEach(rows);
    }

    /**
     * @description True when a stored body may have been cut: it fills the field or carries the truncated mark.
     * @param stored the field value
     * @return whether the full body may be longer
     */
    public static Boolean isCut(String stored) {
        return stored != null && (stored.length() >= FIELD_MAX || stored.contains('...[truncated:'));
    }

    /**
     * @description The newest File of a transaction per title start (REQUEST_PREFIX, RESPONSE_PREFIX, CALLBACK_PREFIX).
     * @param transactionId the transaction
     * @return the File (ContentDocument) Id by title start; starts without a File are absent
     */
    public static Map<String, Id> fileIds(Id transactionId) {
        Map<String, Id> result = new Map<String, Id>();
        if (transactionId == null) {
            return result;
        }
        List<ContentDocumentLink> links = (List<ContentDocumentLink>) IntegrationHubData.query(
            'SELECT ContentDocumentId, ContentDocument.Title FROM ContentDocumentLink WHERE LinkedEntityId = :id '
            + 'ORDER BY SystemModstamp DESC LIMIT 50', new Map<String, Object>{ 'id' => transactionId });
        for (ContentDocumentLink link : links) {
            String prefix = prefixOf(link.ContentDocument.Title);
            if (prefix != null && !result.containsKey(prefix)) {
                result.put(prefix, link.ContentDocumentId);
            }
        }
        return result;
    }

    /**
     * @description The full body: the field value, or the newest File with that title start when the field was cut.
     * @param transactionId the transaction
     * @param prefix RESPONSE_PREFIX or CALLBACK_PREFIX
     * @param stored the field value
     * @return the full body, or the field value when there is no File
     */
    public static String fullBody(Id transactionId, String prefix, String stored) {
        if (!isCut(stored)) {
            return stored;
        }
        Id documentId = fileIds(transactionId).get(prefix);
        if (documentId == null) {
            return stored;
        }
        ContentVersion cv = (ContentVersion) IntegrationHubData.queryFirst(
            'SELECT VersionData FROM ContentVersion WHERE ContentDocumentId = :id AND IsLatest = true LIMIT 1',
            new Map<String, Object>{ 'id' => documentId });
        return cv == null || cv.VersionData == null ? stored : cv.VersionData.toString();
    }

    private static String prefixOf(String title) {
        for (String prefix : new List<String>{ RESPONSE_PREFIX, CALLBACK_PREFIX, REQUEST_PREFIX }) {
            if (title != null && title.startsWith(prefix)) {
                return prefix;
            }
        }
        return null;
    }
}
